public static void main(Args _args)
{
    if (_args == null 
        || _args.record() == null
        || _args.record().TableId != tableNum(ISMBatchableTelemetryParameterSetup))
    {
        throw error(Error::wrongUseOfFunction(funcName()));
    }

    ISMBatchableTelemetryParameterSetup batchableTelemetryParameterSetup = 
        _args.record() as ISMBatchableTelemetryParameterSetup;

    ISMBatchableTelemetryStatusTable statusTable;
    select firstonly1 statusTable
        where statusTable.ParameterSetup == batchableTelemetryParameterSetup.RecId
            && statusTable.Batch != 0;

    Batch batch;
    BatchJob batchJob;
    select firstonly1 batchJob
        exists join batch 
            where batch.RecId == statusTable.Batch
                && batch.BatchJobId == batchJob.RecId;

    ISMBatchableTelemetryHelper::stopBatchJob(batchJob.RecId);
}
